WITH art AS (
  SELECT ROUND(10.0 * SUM(CASE WHEN s.shipment_overview->'route'->>'risk_note' IN ('Low', 'Medium') THEN 1 ELSE 0 END)::numeric / COUNT(*), 2) as score FROM shipments s
),
rrd AS (
  SELECT ROUND(10.0 * SUM(CASE WHEN c.carriercert != 'None' THEN 1 ELSE 0 END)::numeric / COUNT(*), 2) as score FROM carriers c
),
sbp AS (
  SELECT ROUND(10.0 * SUM(CASE WHEN v.veh_qual IN ('Qualified', 'Validated') THEN 1 ELSE 0 END)::numeric / COUNT(*), 2) as score FROM vehicles v
),
smc AS (
  SELECT ROUND(10.0 * SUM(CASE WHEN jsonb_extract_path_text(qc_checklist, 'gdp_quality', 'gdp_compliance') != 'Non-compliant' THEN 1 ELSE 0 END)::numeric / COUNT(*), 2) as score FROM qualitycompliance
)
SELECT 
  ROUND((0.4 * a.score + 0.3 * r.score + 0.2 * b.score + 0.1 * m.score)::numeric, 2) as supply_chain_resilience_score
FROM art a, rrd r, sbp b, smc m;

